def validate_launch_plan(teams):
    """Validate that sequencing is justified. Returns warnings list."""
    warnings = []
    waves = set(t.get('launch_wave', 0) for t in teams)
    if len(waves) > 1:
        for t in teams:
            if t.get('launch_wave', 0) > 0:
                if not t.get('sequencing_justification'):
                    warnings.append(
                        f"ANTI-SEQUENTIAL VIOLATION: {t['team_id']} is in wave "
                        f"{t['launch_wave']} with no justification. "
                        f"Default is wave 0 (parallel). Provide sequencing_justification "
                        f"or move to wave 0."
                    )
                elif not t.get('depends_on_artifacts_from'):
                    warnings.append(
                        f"WEAK JUSTIFICATION: {t['team_id']} has justification but "
                        f"depends_on_artifacts_from is empty. If no artifact dependency "
                        f"exists, move to wave 0."
                    )
    if max(w for w in waves) > 1:
        warnings.append(
            f"THREE OR MORE WAVES detected ({len(waves)} waves). "
            f"This indicates a decomposition failure. Re-analyze task dependencies."
        )
    return warnings
